export function withZMotorSourceLocales(source){
 if(sourceCache.has(source))return sourceCache.get(source);
 if(source.steps.length!==41||source.steps.some(s=>(!Object.hasOwn(sourceCS,s.id)||!Object.hasOwn(sourceDE,s.id))))throw Error('Z motor source locale IDs differ');
 const localeFallbacks={...source.localeFallbacks};delete localeFallbacks.cs;delete localeFallbacks.de;
 const result={...source,localeFallbacks,steps:source.steps.map(s=>({...s,title:s.title.map((v,i)=>i===2?sourceCS[s.id][0]:i===3?sourceDE[s.id][0]:v),body:s.body.map((v,i)=>i===2?sourceCS[s.id][1]:i===3?sourceDE[s.id][1]:v)}))};
 sourceCache.set(source,result);return result;
}
